def compare_one(a, b):
    def convert_to_float(x):
        try:
            if isinstance(x, str):
                return float(x.replace(',', '.'))
            return x
        except ValueError:
            return None

    a_float = convert_to_float(a)
    b_float = convert_to_float(b)

    if a_float is None or b_float is None:
        return None

    if a_float == b_float:
        return None

    return a if a_float > b_float else b
